    description: 'Эта модель — одна из самых популярных поворотных камер для внутреннего видеонаблюдения. Она отличается уникальным дизайном, наличием встроенного микрофона и возможностью вращения на 360°, что делает её идеальным «электронным охранником» для помещений. Внутренняя поворотная Wi-Fi камера Dahua SD29204DB-GNY-W (2 Мп, 4x зум). Dahua SD29204DB-GNY-W — это интеллектуальная PTZ-камера серии WizSense, созданная специально для мониторинга внутренних помещений: офисов, магазинов, аптек и частных интерьеров. Модель сочетает в себе компактность, стильный дизайн и мощную аналитику с искусственным интеллектом. Ключевые преимущества SD29204DB-GNY-W. Выбирая эту модель, вы получаете полный функционал профессиональной системы безопасности в одном устройстве: Обзор 360° и 4х зум: Поворотный механизм позволяет удаленно вращать камеру на полный оборот, а 4-кратное оптическое увеличение (2.8–12 мм) дает возможность рассмотреть номиналы купюр или лица посетителей. Интеллект WizSense: Встроенные алгоритмы глубокого обучения позволяют камере точно распознавать людей и транспорт, игнорируя домашних животных и блики. Поддерживается функция SMD 3.0 (умная детекция движения). Аудиоконтроль: Встроенный высокочувствительный микрофон позволяет записывать звук и мониторить обстановку в реальном времени. Технология Starlight: Камера сохраняет четкую цветную картинку даже при слабом комнатном освещении. Умная ИК-подсветка: Инфракрасные светодиоды обеспечивают видимость до 30 метров в полной темноте, автоматически подстраиваясь под фокусное расстояние (Smart IR). Беспроводная свобода: Модуль Wi-Fi избавляет от необходимости прокладки кабелей по стенам и потолку, сохраняя эстетику интерьера. Разрешение: 2 Мп (1920×1080) Full HD. Скорость записи: 25 кадров в секунду. WDR 120 дБ: Аппаратное расширение динамического диапазона для работы напротив окон и источников яркого света. Хранение данных: Слот для MicroSD карт объемом до 512 Гб. Питание: Стандартное DC 12 В (блок питания обычно входит в комплект). Почему это идеальный выбор для бизнеса? Модель SD29204DB-GNY-W позволяет заменить 2–3 фиксированные камеры в одном зале. Благодаря функции предустановок (Presets), вы можете настроить камеру на автоматическое патрулирование самых важных точек (касса, вход, витрина). Купите Dahua SD29204DB-GNY-W для эффективного контроля вашего бизнеса или дома. Современный дизайн и мощный функционал в одном корпусе!',
